// ========================================================================
// Teller Transaction Sync — Code Node
// ========================================================================
// For each Teller enrollment, fetches transactions for all linked accounts
// using the Teller API with mTLS + Basic Auth.
//
// Requires n8n environment variables:
//   TELLER_CERT_PATH, TELLER_KEY_PATH (mTLS certificate)
//   TOKEN_ENCRYPTION_PASSPHRASE (for decrypting stored access tokens)
// ========================================================================

const fs = require('fs');
const https = require('https');

const enrollments = $input.all();
const results = [];

const certPath = $env.TELLER_CERT_PATH || './certificate.pem';
const keyPath = $env.TELLER_KEY_PATH || './private_key.pem';

for (const enrollment of enrollments) {
  const { enrollment_id, teller_enrollment_id, institution_name, access_token, last_synced_txn_date, account_ids } = enrollment.json;
  let addedCount = 0;
  let errorState = null;

  try {
    const accounts = typeof account_ids === 'string' ? JSON.parse(account_ids) : account_ids;

    for (const accountId of accounts) {
      // Fetch transactions from Teller API
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.teller.io/accounts/${accountId}/transactions`,
        headers: {
          'Authorization': 'Basic ' + Buffer.from(access_token + ':').toString('base64'),
        },
        // Note: mTLS cert must be configured in n8n's HTTP Request node settings
        // or via environment-level TLS configuration
        returnFullResponse: false,
      });

      const txns = Array.isArray(response) ? response : [];

      for (const txn of txns) {
        if (txn.status === 'pending') continue;

        // Skip if older than last sync
        if (last_synced_txn_date && new Date(txn.date) <= new Date(last_synced_txn_date)) continue;

        // Normalize amount: Teller uses negative for debits, we store positive for debits
        const rawAmount = parseFloat(txn.amount);
        const normalizedAmount = rawAmount < 0 ? Math.abs(rawAmount) : -rawAmount;

        results.push({
          json: {
            _action: 'upsert',
            enrollment_id,
            institution_name,
            account_id: accountId,
            transaction_id: txn.id,
            amount: normalizedAmount,
            iso_currency_code: 'USD',
            date: txn.date,
            merchant_name: txn.details?.counterparty?.name || txn.description || null,
            name: txn.description || '',
            category: txn.details?.category || null,
            pending: false,
          }
        });
        addedCount++;
      }
    }

    // Output sync summary
    results.push({
      json: {
        _action: 'update_sync_date',
        enrollment_id,
        institution_name,
        added: addedCount,
        sync_date: new Date().toISOString().split('T')[0],
      }
    });

  } catch (err) {
    const status = err?.response?.status || err?.statusCode || 0;
    if (status === 401 || status === 403) {
      errorState = 'DISCONNECTED';
    }
    results.push({
      json: {
        _action: 'error',
        enrollment_id,
        institution_name,
        teller_enrollment_id,
        error: err.message,
        error_state: errorState || 'ERROR',
      }
    });
  }
}

return results;

